import{n as e}from"./BliATjOS.js";var t=e(`journal`,{state:()=>({entries:[],showCheckin:!1}),getters:{chartData(e){return e.entries.slice().sort((e,t)=>new Date(e.date).getTime()-new Date(t.date).getTime()).map((e,t)=>({day:t+1,mood:e.mood,date:e.date,note:e.note}))},lastEntry(e){return e.entries.length?e.entries[e.entries.length-1]:null}},actions:{init(){let e=new Date().toISOString().split(`T`)[0],t=localStorage.getItem(`last-checkin-date`);this.showCheckin=t!==e},saveCheckin(e){let t=new Date().toISOString().split(`T`)[0],n=this.entries.find(e=>e.date===t);n?(n.mood=e.mood,n.note=e.note):this.entries.push({id:crypto.randomUUID(),date:t,mood:e.mood,note:e.note}),localStorage.setItem(`last-checkin-date`,t),this.showCheckin=!1},closeCheckin(){this.showCheckin=!1},getEntryByDate(e){return this.entries.find(t=>t.date===e)},deleteEntry(e){this.entries=this.entries.filter(t=>t.id!==e)},addNote(e){let t=new Date().toISOString().split(`T`)[0];this.entries.push({id:crypto.randomUUID(),date:t,note:e})}},persist:!0});export{t};